const nextImageScan = `-- name: NextImageScan :one
SELECT id, image_key, pull_ref, local_ref, built_on_server_id, org_id, production, state, priority, attempts, next_attempt_at, server_id, distro, packages, sbom_bytes, sbom_at, matched_at, db_built_at, critical, high, medium, low, other, fixable, kev, truncated, worst_fix, error, created_at FROM image_scans
WHERE state = 'queued' AND (next_attempt_at IS NULL OR next_attempt_at <= +?1)
  AND (production = 0 OR +?2 = 1)
ORDER BY priority, id LIMIT 1
`

type NextImageScanParams struct {
	Now               *int64
	ProductionBuilder interface{}
}

// The next scan to run: queued, due, and one a builder there is may
// scan (production ones only with a builder that accepts production).
func (q *Queries) NextImageScan(ctx context.Context, arg NextImageScanParams) (ImageScan, error) {
	row := q.db.QueryRowContext(ctx, nextImageScan, arg.Now, arg.ProductionBuilder)
	var i ImageScan
	err := row.Scan(
		&i.ID,
		&i.ImageKey,
		&i.PullRef,
		&i.LocalRef,
		&i.BuiltOnServerID,
		&i.OrgID,
		&i.Production,
		&i.State,
		&i.Priority,
		&i.Attempts,
		&i.NextAttemptAt,
		&i.ServerID,
		&i.Distro,
		&i.Packages,
		&i.SbomBytes,
		&i.SbomAt,
		&i.MatchedAt,
		&i.DbBuiltAt,
		&i.Critical,
		&i.High,
		&i.Medium,
		&i.Low,
		&i.Other,
		&i.Fixable,
		&i.Kev,
		&i.Truncated,
		&i.WorstFix,
		&i.Error,
		&i.CreatedAt,
	)
	return i, err
}

const nextImageScanRetry = `-- name: NextImageScanRetry :one
SELECT CAST(coalesce(min(next_attempt_at), 0) AS INTEGER) AS due FROM image_scans
WHERE state = 'queued' AND next_attempt_at > +?1
`

// When the earliest scan waiting to retry is due (0 for none).
func (q *Queries) NextImageScanRetry(ctx context.Context, now *int64) (int64, error) {
	row := q.db.QueryRowContext(ctx, nextImageScanRetry, now)
	var due int64
	err := row.Scan(&due)
	return due, err
}

const raiseImageScanPriority = `-- name: RaiseImageScanPriority :exec
UPDATE image_scans SET production = max(production, ?1), priority = min(priority, ?2)
WHERE id = +?3
`

type RaiseImageScanPriorityParams struct {
	Production interface{}
	Priority   interface{}
	ID         int64
}

// A scan another, more important release uses now: production first.
func (q *Queries) RaiseImageScanPriority(ctx context.Context, arg RaiseImageScanPriorityParams) error {
	_, err := q.db.ExecContext(ctx, raiseImageScanPriority, arg.Production, arg.Priority, arg.ID)
	return err
}

const requeueImageScan = `-- name: RequeueImageScan :exec
UPDATE image_scans SET state = 'queued', attempts = 0, next_attempt_at = NULL, error = '',
    priority = min(priority, ?1)
WHERE id = +?2 AND state != 'scanning'
`

type RequeueImageScanParams struct {
	Priority interface{}
	ID       int64
}

// Scan again: from its SBOM when it has one (match only), else in full.
func (q *Queries) RequeueImageScan(ctx context.Context, arg RequeueImageScanParams) error {
	_, err := q.db.ExecContext(ctx, requeueImageScan, arg.Priority, arg.ID)
	return err
}

const requeueInterruptedScans = `-- name: RequeueInterruptedScans :exec
UPDATE image_scans SET state = 'queued' WHERE state = 'scanning'
`

// On start: scans the last daemon stopped in the middle of run again.
func (q *Queries) RequeueInterruptedScans(ctx context.Context) error {
	_, err := q.db.ExecContext(ctx, requeueInterruptedScans)
	return err
}

